/**
 * Column geometry helpers shared by both renderers.
 *
 * `getColumnPinningStyle` previously existed twice — once in `lib/data-table.ts`
 * (semantic table, boxShadow separators) and once in `lib/data-grid.ts` (CSS
 * grid, RTL-aware). This is the merged implementation; `dir` selects the
 * left/right offset behavior for RTL.
 *
 * Cố ý KHÔNG trả số px nào ở đây — cả độ rộng lẫn offset ghim đều đi qua CSS
 * variable (`computeColumnSizeVars` + `calc(var(...) * 1px)` ở nơi gọi) để
 * resize mượt, không phụ thuộc React re-render.
 */

import type { Column } from "@tanstack/react-table";

import type { Direction } from "@/types/data-grid";

/** Approximate width of one header character, used to derive a minimum size. */
const HEADER_CHAR_WIDTH_PX = 8.5;
const HEADER_ICON_WIDTH_PX = 28;
const HEADER_PADDING_PX = 24;

export function getColumnPinningStyle<TData>({
  column,
  dir = "ltr",
  withBorder = false,
  background = "var(--background)",
}: {
  column: Column<TData>;
  dir?: Direction;
  withBorder?: boolean;
  /**
   * Nền cho ô đang ghim (phải đặc, không alpha) — mặc định khớp nền trang.
   * Header truyền `var(--muted)` để khớp với nền `bg-muted` của `<thead>`,
   * tránh mảng ghim nổi màu khác với phần header còn lại.
   */
  background?: string;
}): React.CSSProperties {
  const isPinned = column.getIsPinned();

  if (!isPinned) {
    return { position: "relative" };
  }

  // Offset ghim cũng đi qua biến CSS chứ không phải số px tính lúc render:
  // `column.getStart("left")` chỉ đúng sau khi React render lại, nên kéo một
  // cột ghim sẽ không thể mượt nếu neo vào nó. Xem `computeColumnSizeVars`.
  const startOffset = `calc(var(--col-${column.id}-start, 0) * 1px)`;
  const endOffset = `calc(var(--col-${column.id}-end, 0) * 1px)`;
  const isRtl = dir === "rtl";

  return {
    position: "sticky",
    // In RTL the visual "left" edge is `right`, so the offsets swap.
    left:
      isPinned === "left"
        ? isRtl
          ? undefined
          : startOffset
        : isRtl
          ? endOffset
          : undefined,
    right:
      isPinned === "right"
        ? isRtl
          ? undefined
          : endOffset
        : isRtl
          ? startOffset
          : undefined,
    zIndex: isPinned === "left" ? 2 : 3,
    background,
    // Viền phân cách của MỌI cột đang ghim (không chỉ cột ở rìa vùng ghim):
    // trái ghim vẽ ở cạnh phải, phải ghim vẽ ở cạnh trái. Bắt buộc dùng inset
    // box-shadow thay vì class `border-e` — các cột ghim cùng z-index (2/3),
    // cột đứng sau trong DOM vẽ đè lên cột đứng trước tại đúng pixel giáp
    // ranh, nên border-e (vẽ ở mép ngoài box) dễ bị cột kế tiếp che mất.
    // box-shadow inset vẽ lùi vào bên trong 1px, nằm trong vùng sơn riêng
    // của chính cột đó nên không bị cột khác đè.
    boxShadow: withBorder
      ? isPinned === "left"
        ? "inset -1px 0 0 0 var(--border)"
        : "inset 1px 0 0 0 var(--border)"
      : undefined,
  };
}

/**
 * Bump `minSize` so a header label is never clipped before the user resizes.
 * Ported from Landsoft's `withHeaderAwareColumnSizes`.
 *
 * Documented consequence: a column declaring `size: 90` with the header
 * "Description" ends up at ~110 — the header width wins.
 */
export function getHeaderAwareMinSize({
  label,
  minSize,
  hasSortIcon = false,
}: {
  label: string;
  minSize?: number;
  hasSortIcon?: boolean;
}): number {
  const textWidth = label.length * HEADER_CHAR_WIDTH_PX;
  const iconWidth = hasSortIcon ? HEADER_ICON_WIDTH_PX : 0;
  const required = Math.ceil(textWidth + iconWidth + HEADER_PADDING_PX);

  return Math.max(minSize ?? 0, required);
}

/** Header text of a column def, when it is a plain string. */
export function getHeaderLabel(header: unknown, fallback: string): string {
  return typeof header === "string" ? header : fallback;
}

/**
 * Tính toàn bộ biến CSS mô tả hình học cột của bảng.
 *
 * Tách thành hàm thuần vì có HAI nơi cần cùng một phép tính:
 *
 *   1. `useColumnSizeVars` — đường React bình thường, chạy khi state đổi.
 *   2. `useColumnResize` — đường mệnh lệnh trong lúc kéo, ghi thẳng vào
 *      `style` của container để KHÔNG phải re-render React frame nào.
 *
 * Tham số `overrides` phục vụ đúng trường hợp (2): lúc đang kéo, kích thước
 * mới chưa nằm trong state TanStack, nên truyền đè vào đây để tính ra hình
 * học của khung hình kế tiếp mà không cần commit state.
 *
 * Các biến sinh ra:
 *   --table-total-size   tổng độ rộng bảng (cho `table-layout: fixed`)
 *   --header-{id}-size   độ rộng ô header (header có thể gộp nhiều cột)
 *   --col-{id}-size      độ rộng cột
 *   --col-{id}-start     offset `left` của cột ghim trái (cộng dồn)
 *   --col-{id}-end       offset `right` của cột ghim phải (cộng dồn)
 *
 * Hai biến offset tồn tại vì cột ghim định vị `sticky` theo tổng độ rộng của
 * các cột ghim đứng trước nó. Nếu để `column.getStart("left")` trả số px như
 * trước, offset chỉ đúng sau khi React render lại — tức là kéo cột ghim sẽ
 * không thể mượt. Đẩy nốt offset qua biến CSS thì trình duyệt tự cascade.
 */

import type { RowData, Table } from "@tanstack/react-table";

export type ColumnSizeVars = Record<string, number>;

export function computeColumnSizeVars<TData extends RowData>(
  table: Table<TData>,
  overrides?: Record<string, number>,
): ColumnSizeVars {
  const sizeOf = (columnId: string, fallback: number) =>
    overrides?.[columnId] ?? fallback;

  const vars: ColumnSizeVars = {};
  const leafColumns = table.getVisibleLeafColumns();

  let totalSize = 0;
  for (const column of leafColumns) {
    const size = sizeOf(column.id, column.getSize());
    vars[`--col-${column.id}-size`] = size;
    totalSize += size;
  }
  vars["--table-total-size"] = totalSize;

  for (const header of table.getFlatHeaders()) {
    const leaves = header.column.getLeafColumns();
    vars[`--header-${header.id}-size`] =
      leaves.length > 1
        ? leaves.reduce((sum, leaf) => sum + sizeOf(leaf.id, leaf.getSize()), 0)
        : sizeOf(header.column.id, header.column.getSize());
  }

  // Ghim trái cộng dồn từ mép trái; ghim phải cộng dồn ngược từ mép phải.
  let startOffset = 0;
  for (const column of leafColumns) {
    if (column.getIsPinned() !== "left") continue;
    vars[`--col-${column.id}-start`] = startOffset;
    startOffset += vars[`--col-${column.id}-size`] ?? 0;
  }

  let endOffset = 0;
  for (let index = leafColumns.length - 1; index >= 0; index--) {
    const column = leafColumns[index];
    if (!column || column.getIsPinned() !== "right") continue;
    vars[`--col-${column.id}-end`] = endOffset;
    endOffset += vars[`--col-${column.id}-size`] ?? 0;
  }

  return vars;
}

/**
 * Density and sticky presentation tokens.
 *
 * Landsoft's MRT setup locked density to "compact" with `!important` overrides,
 * which made the density toggle a visible no-op. Here the toggle is real: every
 * density maps to a distinct class set and nothing overrides it.
 */

import type { ColumnAlign, Density } from "@/types/table";

export const DENSITY_VALUES: Density[] = ["compact", "comfortable", "spacious"];

interface DensityTokens {
  cell: string;
  head: string;
  rowHeight: number;
}

const densityTokens: Record<Density, DensityTokens> = {
  compact: {
    cell: "px-3 py-1 text-xs",
    head: "h-8 px-3 text-xs",
    rowHeight: 32,
  },
  comfortable: {
    cell: "px-3 py-2 text-sm",
    head: "h-10 px-3 text-sm",
    rowHeight: 40,
  },
  spacious: {
    cell: "px-4 py-3.5 text-sm",
    head: "h-12 px-4 text-sm",
    rowHeight: 52,
  },
};

export function getDensityCellClass(density: Density) {
  return densityTokens[density].cell;
}

export function getDensityHeadClass(density: Density) {
  return densityTokens[density].head;
}

export function getDensityRowHeight(density: Density) {
  return densityTokens[density].rowHeight;
}

export function getNextDensity(density: Density): Density {
  const index = DENSITY_VALUES.indexOf(density);
  return DENSITY_VALUES[(index + 1) % DENSITY_VALUES.length] ?? "comfortable";
}

const alignClasses: Record<ColumnAlign, string> = {
  start: "text-left justify-start",
  center: "text-center justify-center",
  end: "text-right justify-end",
};

export function getAlignClass(align: ColumnAlign | undefined) {
  return align ? alignClasses[align] : alignClasses.start;
}

import type { TableLocalization } from "@/types/table";

import { tableLocalizationEn } from "./en";
import { tableLocalizationVi } from "./vi";

export { tableLocalizationEn, tableLocalizationVi };

export const defaultTableLocalization = tableLocalizationEn;

/** Interpolate `{placeholder}` tokens, e.g. `filterByColumn`. */
export function formatLocalized(
  template: string,
  values: Record<string, string | number>,
) {
  return template.replace(/\{(\w+)\}/g, (match, key: string) =>
    key in values ? String(values[key]) : match,
  );
}

export function resolveLocalization(
  overrides?: Partial<TableLocalization>,
): TableLocalization {
  return overrides
    ? { ...defaultTableLocalization, ...overrides }
    : defaultTableLocalization;
}

"use client";

import type { RowData, Table } from "@tanstack/react-table";
import * as React from "react";

import { computeColumnSizeVars } from "@/lib/table/column-size-vars";

/**
 * Biến CSS cho hình học cột — kỹ thuật TanStack Table khuyến nghị để resize
 * mượt, data-grid đã dùng sẵn.
 *
 * Vấn đề nếu không có: mỗi lần `columnSizing` đổi thì `table` (từ
 * `useReactTable`) đổi reference → mọi component đọc `table` re-render. Nếu
 * từng ô tự gọi `column.getSize()` rồi gán `style.width` bằng số, React phải
 * patch DOM ở TỪNG ô (20 hàng × 21 cột ≈ 420 lần) mỗi khung hình khi kéo.
 *
 * Gom tất cả vào MỘT object gán MỘT LẦN lên container; mỗi ô chỉ tham chiếu
 * `calc(var(--col-x-size) * 1px)` — chuỗi cố định không đổi qua các lần
 * render, nên trình duyệt tự cascade giá trị mới mà React không phải ghi lại
 * DOM của ô nào.
 *
 * Đây là đường React "bình thường" (ẩn/hiện cột, ghim, đổi thứ tự, chốt kích
 * thước sau khi kéo xong). Riêng lúc đang kéo, `useColumnResize` ghi thẳng
 * cùng bộ biến này vào DOM để không tốn lượt render nào.
 */
export function useColumnSizeVars<TData extends RowData>(
  table: Table<TData>,
): React.CSSProperties {
  const state = table.getState();

  // biome-ignore lint/correctness/useExhaustiveDependencies: `table` luôn đổi reference sau mỗi state update nên cố tình không đưa vào deps; chỉ 5 slice dưới đây mới thật sự làm hình học cột thay đổi.
  return React.useMemo(
    () => computeColumnSizeVars(table) as React.CSSProperties,
    [
      state.columnSizing,
      state.columnSizingInfo,
      state.columnVisibility,
      state.columnPinning,
      state.columnOrder,
    ],
  );
}

"use client";

/**
 * Cử chỉ kéo resize cột — thay hoàn toàn `header.getResizeHandler()`.
 *
 * Vì sao không dùng handler của TanStack: với `columnResizeMode: "onChange"`,
 * mỗi `mousemove` nó bắn HAI lần cập nhật state (`setColumnSizingInfo` +
 * `setColumnSizing`). Chuột bắn 100-200 sự kiện/giây trong khi màn hình chỉ vẽ
 * 60 khung/giây, nên phần lớn số lần cập nhật đó không bao giờ kịp hiển thị —
 * chỉ tốn công. Nặng hơn nữa: ở màn Employees `columnSizing` là controlled
 * state chảy ngược lên store cấu hình bảng, nên MỖI sự kiện chuột kéo theo
 * `JSON.stringify` + `localStorage.setItem` đồng bộ và một lượt re-render cả
 * màn hình (toolbar, ô tìm kiếm, panel chi tiết...). Đó là nguồn giật thật sự.
 *
 * Cách làm ở đây, mượn đúng nguyên tắc của data-grid rồi đẩy thêm một bước:
 *
 *   mousedown  → 1 lần setState (đánh dấu cột đang resize, để tô sáng tay kéo)
 *   mousemove  → 0 lần setState. Gộp theo khung hình rồi ghi THẲNG biến CSS
 *                vào `style` của container. Trình duyệt tự cascade độ rộng
 *                xuống mọi ô; React đứng ngoài hoàn toàn.
 *   mouseup    → 1 lần setState (chốt kích thước, lúc này mới ghi localStorage)
 *
 * Tổng cộng 2 lượt render cho cả cử chỉ, thay vì ~200 như trước.
 */

import type { Header, RowData, Table } from "@tanstack/react-table";
import * as React from "react";

import {
  type ColumnSizeVars,
  computeColumnSizeVars,
} from "@/lib/table/column-size-vars";

const CONTAINER_SELECTOR = '[data-slot="data-table-container"]';

function getClientX(event: MouseEvent | TouchEvent): number {
  return "touches" in event ? (event.touches[0]?.clientX ?? 0) : event.clientX;
}

export type ColumnResizeStarter<TData extends RowData> = (
  header: Header<TData, unknown>,
  event: React.MouseEvent | React.TouchEvent,
) => void;

export function useColumnResize<TData extends RowData>(
  table: Table<TData>,
): ColumnResizeStarter<TData> {
  return React.useCallback(
    (header, startEvent) => {
      const column = header.column;
      if (!column.getCanResize()) return;

      const container = (
        startEvent.currentTarget as HTMLElement
      ).closest<HTMLElement>(CONTAINER_SELECTOR);
      if (!container) return;

      const defaultColumnDef = table._getDefaultColumnDef();
      const startSize = column.getSize();
      const startX = getClientX(
        startEvent.nativeEvent as MouseEvent | TouchEvent,
      );
      const minSize = column.columnDef.minSize ?? defaultColumnDef.minSize ?? 0;
      const maxSize =
        column.columnDef.maxSize ??
        defaultColumnDef.maxSize ??
        Number.MAX_SAFE_INTEGER;

      // Cột ghim phải neo vào mép phải bảng: cạnh phải không nhúc nhích được
      // nên tay kéo nằm ở cạnh TRÁI, và kéo sang trái mới là phình to.
      const direction = column.getIsPinned() === "right" ? -1 : 1;

      table.setColumnSizingInfo((old) => ({
        ...old,
        isResizingColumn: column.id,
      }));

      let rafId: number | null = null;
      let currentSize = startSize;
      let painted: ColumnSizeVars = {};

      function paint() {
        rafId = null;
        const next = computeColumnSizeVars(table, { [column.id]: currentSize });
        for (const [key, value] of Object.entries(next)) {
          // Chỉ ghi biến thật sự đổi — kéo một cột thường chỉ động tới vài
          // biến, không cần đụng cả bảng mỗi khung hình.
          if (painted[key] === value) continue;
          container?.style.setProperty(key, String(value));
        }
        painted = next;
      }

      function onMove(event: MouseEvent | TouchEvent) {
        const delta = (getClientX(event) - startX) * direction;
        currentSize = Math.min(maxSize, Math.max(minSize, startSize + delta));
        rafId ??= requestAnimationFrame(paint);
      }

      function onEnd() {
        if (rafId !== null) {
          cancelAnimationFrame(rafId);
          rafId = null;
        }
        document.removeEventListener("mousemove", onMove);
        document.removeEventListener("mouseup", onEnd);
        document.removeEventListener("touchmove", onMove);
        document.removeEventListener("touchend", onEnd);

        // Cố ý KHÔNG xoá biến đã ghi tay: lượt render sau của React sẽ ghi đè
        // đúng những giá trị này. Xoá trước sẽ để lộ một khung hình về kích
        // thước cũ trước khi React kịp commit.
        table.setColumnSizing((old) => ({ ...old, [column.id]: currentSize }));
        table.setColumnSizingInfo((old) => ({
          ...old,
          isResizingColumn: false,
        }));
      }

      document.addEventListener("mousemove", onMove);
      document.addEventListener("mouseup", onEnd);
      document.addEventListener("touchmove", onMove, { passive: true });
      document.addEventListener("touchend", onEnd);
    },
    [table],
  );
}

"use client";

/**
 * Shared table core — the analog of MRT's `useMRT_TableOptions` +
 * `useMRT_TableInstance` + `useMRT_DisplayColumns`.
 *
 * The contract this establishes is the whole point of the refactor: **the table
 * instance is the only transport**. Renderers, slot props, localization and the
 * extra MRT-style state all ride on `table.options` / `table.getState()`, so a
 * renderer only ever needs `{ table }` — never a spread of loose props.
 *
 * Layering:
 *   useTableCore            ← this file: defaults, display columns, extra state
 *     ├─ useDataTable       ← adds URL state, pagination, advanced filters
 *     └─ useDataGrid        ← adds cell selection, editing, paste, virtualizer
 */

import {
  getCoreRowModel,
  type RowData,
  type TableState,
  type Table as TanstackTable,
  useReactTable,
} from "@tanstack/react-table";
import * as React from "react";

import { resolveLocalization } from "@/lib/table/localization";
import type {
  TableCoreOptions,
  TableCoreState,
  TableExtraState,
  TableLocalization,
  TableSlotProps,
} from "@/types/table";
import { useTableDisplayColumns } from "./use-table-display-columns";
import {
  type TableExtraStateHandle,
  useTableExtraState,
} from "./use-table-extra-state";

/**
 * The MRT-style additions layered on top of TanStack's resolved options.
 * Kept separate from `TableOptionsResolved` so the instance type below can
 * intersect the two and stay assignable to a plain `Table<TData>`.
 */
export interface DefinedTableCoreOptions<TData extends RowData>
  extends Omit<
    TableCoreOptions<TData>,
    "columns" | "data" | "state" | "initialState"
  > {
  localization: TableLocalization;
  slotProps: TableSlotProps<TData>;
  layoutMode: NonNullable<TableCoreOptions<TData>["layoutMode"]>;
  enableTopToolbar: boolean;
  enableBottomToolbar: boolean;
  enableToolbarInternalActions: boolean;
  enableDensityToggle: boolean;
  enableFullScreenToggle: boolean;
  enableColumnVisibilityToggle: boolean;
  enableColumnFilterToggle: boolean;
  enableTableSettings: boolean;
  enableStickyHeader: boolean;
  enableStickyFooter: boolean;
  enableColumnBorders: boolean;
  enablePagination: boolean;
  pageSizeOptions: number[];
  enableRowNumbers: boolean;
  enableRowActions: boolean;
  positionActionsColumn: "first" | "last";
  positionExpandColumn: "first" | "last";
  idPrefix: string;
}

/**
 * The instance every renderer takes.
 *
 * `options` intersects TanStack's resolved options with ours, so the instance
 * remains a valid `Table<TData>` and can still be handed to any plain TanStack
 * helper. Only `getState` is replaced outright — an intersection there would
 * resolve to the narrower TanStack return type and hide the extra state.
 */
export type TableCoreInstance<TData extends RowData> = Omit<
  TanstackTable<TData>,
  "getState"
> & {
  options: TanstackTable<TData>["options"] & DefinedTableCoreOptions<TData>;
  getState: () => TableCoreState;
  /** Setters for the extra state, mirroring TanStack's `setX` naming. */
  extra: TableExtraStateHandle;
};

const DEFAULT_PAGE_SIZE_OPTIONS = [10, 20, 30, 40, 50];

let idCounter = 0;

export function useTableCore<TData extends RowData>(
  options: TableCoreOptions<TData>,
): TableCoreInstance<TData> {
  const {
    columns,
    state,
    initialState,
    localization: localizationOverrides,
    slotProps,
    layoutMode = "semantic",
    enableTopToolbar = true,
    enableBottomToolbar = true,
    enableToolbarInternalActions = true,
    enableDensityToggle = true,
    enableFullScreenToggle = true,
    enableColumnVisibilityToggle = true,
    enableColumnFilterToggle = true,
    enableTableSettings = false,
    enableStickyHeader = true,
    enableStickyFooter = false,
    enableColumnBorders = false,
    enablePagination = true,
    pageSizeOptions = DEFAULT_PAGE_SIZE_OPTIONS,
    enableRowSelection,
    enableRowNumbers = false,
    enableRowActions = false,
    positionActionsColumn = "last",
    positionExpandColumn = "first",
    renderRowActions,
    renderDetailPanel,
    renderTopToolbar,
    renderTopToolbarCustomActions,
    renderBottomToolbarCustomActions,
    renderToolbarAlertBannerContent,
    renderEmptyRowsFallback,
    idPrefix: idPrefixProp,
    ...tableOptions
  } = options;

  // Stable per-instance prefix so two tables on one page keep distinct DOM ids.
  const idPrefix = React.useMemo(
    () => idPrefixProp ?? `dt-${++idCounter}`,
    [idPrefixProp],
  );

  const localization = React.useMemo(
    () => resolveLocalization(localizationOverrides),
    [localizationOverrides],
  );

  const extraStateInput = React.useMemo(() => pickExtraState(state), [state]);

  const extra = useTableExtraState({
    initialState: pickExtraState(initialState),
    state: extraStateInput,
  });

  const allColumns = useTableDisplayColumns<TData>({
    columns,
    localization,
    enableRowSelection,
    enableRowNumbers,
    enableRowActions,
    positionActionsColumn,
    positionExpandColumn,
    renderRowActions,
    renderDetailPanel,
  });

  const table = useReactTable<TData>({
    getCoreRowModel: getCoreRowModel(),
    ...tableOptions,
    columns: allColumns,
    enableRowSelection,
    state: pickTanstackState(state),
    initialState: pickTanstackState(initialState),
  });

  // Attach the MRT-style surface so renderers can read everything off `table`.
  const instance = table as unknown as TableCoreInstance<TData>;

  instance.options = {
    ...table.options,
    localization,
    slotProps: slotProps ?? {},
    layoutMode,
    enableTopToolbar,
    enableBottomToolbar,
    enableToolbarInternalActions,
    enableDensityToggle,
    enableFullScreenToggle,
    enableColumnVisibilityToggle,
    enableColumnFilterToggle,
    enableTableSettings,
    enableStickyHeader,
    enableStickyFooter,
    enableColumnBorders,
    enablePagination,
    pageSizeOptions,
    enableRowNumbers,
    enableRowActions,
    positionActionsColumn,
    positionExpandColumn,
    renderRowActions,
    renderDetailPanel,
    renderTopToolbar,
    renderTopToolbarCustomActions,
    renderBottomToolbarCustomActions,
    renderToolbarAlertBannerContent,
    renderEmptyRowsFallback,
    idPrefix,
  };

  const getTanstackState = table.getState;
  instance.getState = () =>
    ({ ...getTanstackState(), ...extractExtraState(extra) }) as TableCoreState;
  instance.extra = extra;

  return instance;
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

const EXTRA_STATE_KEYS = [
  "density",
  "isFullScreen",
  "showColumnFilters",
  "showGlobalFilter",
  "showAlertBanner",
  "showSkeletons",
  "showProgressBars",
  "isLoading",
] as const satisfies readonly (keyof TableExtraState)[];

function pickExtraState(
  state: Partial<TableCoreState> | undefined,
): Partial<TableExtraState> | undefined {
  if (!state) return undefined;

  const picked: Partial<TableExtraState> = {};
  let found = false;
  for (const key of EXTRA_STATE_KEYS) {
    if (state[key] !== undefined) {
      // @ts-expect-error — key is a valid TableExtraState key by construction
      picked[key] = state[key];
      found = true;
    }
  }

  return found ? picked : undefined;
}

function pickTanstackState(
  state: Partial<TableCoreState> | undefined,
): Partial<TableState> | undefined {
  if (!state) return undefined;

  const rest = { ...state } as Record<string, unknown>;
  for (const key of EXTRA_STATE_KEYS) {
    delete rest[key];
  }

  return rest as Partial<TableState>;
}

function extractExtraState(extra: TableExtraStateHandle): TableExtraState {
  return {
    density: extra.density,
    isFullScreen: extra.isFullScreen,
    showColumnFilters: extra.showColumnFilters,
    showGlobalFilter: extra.showGlobalFilter,
    showAlertBanner: extra.showAlertBanner,
    showSkeletons: extra.showSkeletons,
    showProgressBars: extra.showProgressBars,
    isLoading: extra.isLoading,
  };
}

"use client";

/**
 * Injects the built-in display columns, mirroring MRT's `useMRT_DisplayColumns`.
 *
 * Order matches MRT: expand → select → numbers → …data… → actions, with
 * `positionActionsColumn` / `positionExpandColumn` able to move the two
 * repositionable ones to the front or back.
 */

import type { ColumnDef, Row, RowData, Table } from "@tanstack/react-table";
import { ChevronDown, ChevronRight } from "lucide-react";
import * as React from "react";

import { getTableSelectColumn } from "@/components/table/table-select-column";
import { DISPLAY_COLUMN_IDS, type TableLocalization } from "@/types/table";

/**
 * TanStack types accessor columns as `AnyColumnDef<TData>`; a heterogeneous
 * column array cannot be expressed without it.
 */
// biome-ignore lint/suspicious/noExplicitAny: required by TanStack's ColumnDef contract
type AnyColumnDef<TData extends RowData> = ColumnDef<TData, any>;

interface UseTableDisplayColumnsProps<TData extends RowData> {
  columns: AnyColumnDef<TData>[];
  localization: TableLocalization;
  enableRowSelection?: boolean | ((row: Row<TData>) => boolean);
  enableRowNumbers?: boolean;
  enableRowActions?: boolean;
  positionActionsColumn?: "first" | "last";
  positionExpandColumn?: "first" | "last";
  renderRowActions?: (context: {
    row: Row<TData>;
    table: Table<TData>;
  }) => React.ReactNode;
  renderDetailPanel?: (context: {
    row: Row<TData>;
    table: Table<TData>;
  }) => React.ReactNode;
}

/**
 * Một cột duy nhất cho STT và ô chọn dòng.
 *
 * Tách làm hai cột thì tắt "chọn nhiều dòng" sẽ mất luôn STT, mà để cạnh nhau
 * lại tốn hai cột cho cùng một chỗ. Gộp lại: STT hiện mặc định, hover hoặc khi
 * dòng được chọn mới đổi thành checkbox — giống hệt data-grid.
 */
function buildSelectColumn<TData extends RowData>({
  localization,
  enableRowNumbers,
  enableRowSelection,
}: {
  localization: TableLocalization;
  enableRowNumbers: boolean;
  enableRowSelection: boolean;
}): AnyColumnDef<TData> {
  // Vừa số vừa checkbox cần rộng hơn ô chọn thuần.
  const size = enableRowNumbers ? 52 : 40;

  return getTableSelectColumn<TData>({
    id: DISPLAY_COLUMN_IDS.select,
    size,
    minSize: size,
    maxSize: enableRowNumbers ? 72 : 40,
    enableRowMarkers: enableRowNumbers,
    readOnly: !enableRowSelection,
    enableSorting: false,
    enableHiding: false,
    enableResizing: false,
    enableColumnFilter: false,
    meta: {
      label: enableRowSelection ? localization.select : localization.rowNumbers,
      align: "center",
    },
  }) as AnyColumnDef<TData>;
}

function buildExpandColumn<TData extends RowData>(
  localization: TableLocalization,
): AnyColumnDef<TData> {
  return {
    id: DISPLAY_COLUMN_IDS.expand,
    size: 40,
    minSize: 40,
    maxSize: 40,
    enableSorting: false,
    enableHiding: false,
    enableResizing: false,
    enableColumnFilter: false,
    meta: { label: localization.expand, align: "center" },
    header: () => null,
    cell: ({ row }) =>
      row.getCanExpand() ? (
        <button
          type="button"
          aria-label={localization.expand}
          aria-expanded={row.getIsExpanded()}
          className="inline-flex size-6 items-center justify-center rounded-sm text-muted-foreground hover:bg-accent"
          onClick={row.getToggleExpandedHandler()}
        >
          {row.getIsExpanded() ? (
            <ChevronDown className="size-4" />
          ) : (
            <ChevronRight className="size-4" />
          )}
        </button>
      ) : null,
  };
}

function buildActionsColumn<TData extends RowData>(
  localization: TableLocalization,
  renderRowActions: NonNullable<
    UseTableDisplayColumnsProps<TData>["renderRowActions"]
  >,
): AnyColumnDef<TData> {
  return {
    id: DISPLAY_COLUMN_IDS.actions,
    // 3 × 24px buttons + 2 × 8px gaps + 2 × 12px padding
    size: 120,
    minSize: 112,
    maxSize: 160,
    enableSorting: false,
    enableHiding: false,
    enableResizing: false,
    enableColumnFilter: false,
    meta: { label: localization.actions, align: "center" },
    header: () => localization.actions,
    cell: ({ row, table }) => renderRowActions({ row, table }),
  };
}

export function useTableDisplayColumns<TData extends RowData>({
  columns,
  localization,
  enableRowSelection,
  enableRowNumbers,
  enableRowActions,
  positionActionsColumn = "last",
  positionExpandColumn = "first",
  renderRowActions,
  renderDetailPanel,
}: UseTableDisplayColumnsProps<TData>): AnyColumnDef<TData>[] {
  return React.useMemo(() => {
    const leading: AnyColumnDef<TData>[] = [];
    const trailing: AnyColumnDef<TData>[] = [];

    if (renderDetailPanel) {
      const expandColumn = buildExpandColumn<TData>(localization);
      (positionExpandColumn === "first" ? leading : trailing).push(
        expandColumn,
      );
    }

    // Một cột lo cả STT lẫn ô chọn; chỉ bỏ hẳn khi tắt cả hai.
    if (enableRowSelection || enableRowNumbers) {
      leading.push(
        buildSelectColumn<TData>({
          localization,
          enableRowNumbers: !!enableRowNumbers,
          enableRowSelection: !!enableRowSelection,
        }),
      );
    }

    if (enableRowActions && renderRowActions) {
      const actionsColumn = buildActionsColumn<TData>(
        localization,
        renderRowActions,
      );
      (positionActionsColumn === "first" ? leading : trailing).push(
        actionsColumn,
      );
    }

    // Caller-provided display columns win — do not inject a duplicate id.
    const existingIds = new Set(columns.map((column) => column.id));
    const keep = (column: AnyColumnDef<TData>) =>
      !column.id || !existingIds.has(column.id);

    return [...leading.filter(keep), ...columns, ...trailing.filter(keep)];
  }, [
    columns,
    localization,
    enableRowSelection,
    enableRowNumbers,
    enableRowActions,
    positionActionsColumn,
    positionExpandColumn,
    renderRowActions,
    renderDetailPanel,
  ]);
}

"use client";

/**
 * Owns the slice of table state that MRT adds on top of TanStack Table.
 *
 * Each key follows the same controlled/uncontrolled contract as TanStack: pass
 * it in `state` to control it, otherwise the hook holds it internally.
 */

import * as React from "react";

import type { TableExtraState } from "@/types/table";

const defaultExtraState: TableExtraState = {
  density: "comfortable",
  isFullScreen: false,
  showColumnFilters: false,
  showGlobalFilter: false,
  showAlertBanner: false,
  showSkeletons: false,
  showProgressBars: false,
  isLoading: false,
};

export interface UseTableExtraStateProps {
  initialState?: Partial<TableExtraState>;
  state?: Partial<TableExtraState>;
}

export interface TableExtraStateHandle extends TableExtraState {
  setDensity: (density: TableExtraState["density"]) => void;
  setIsFullScreen: (isFullScreen: boolean) => void;
  setShowColumnFilters: (showColumnFilters: boolean) => void;
  setShowGlobalFilter: (showGlobalFilter: boolean) => void;
  setShowAlertBanner: (showAlertBanner: boolean) => void;
}

export function useTableExtraState({
  initialState,
  state,
}: UseTableExtraStateProps): TableExtraStateHandle {
  const [internal, setInternal] = React.useState<TableExtraState>(() => ({
    ...defaultExtraState,
    ...initialState,
  }));

  // A key present in `state` is controlled by the caller and wins.
  const resolved = React.useMemo<TableExtraState>(
    () => ({ ...internal, ...state }),
    [internal, state],
  );

  const setKey = React.useCallback(
    <K extends keyof TableExtraState>(key: K, value: TableExtraState[K]) => {
      setInternal((prev) =>
        prev[key] === value ? prev : { ...prev, [key]: value },
      );
    },
    [],
  );

  return React.useMemo(
    () => ({
      ...resolved,
      setDensity: (density) => setKey("density", density),
      setIsFullScreen: (isFullScreen) => setKey("isFullScreen", isFullScreen),
      setShowColumnFilters: (showColumnFilters) =>
        setKey("showColumnFilters", showColumnFilters),
      setShowGlobalFilter: (showGlobalFilter) =>
        setKey("showGlobalFilter", showGlobalFilter),
      setShowAlertBanner: (showAlertBanner) =>
        setKey("showAlertBanner", showAlertBanner),
    }),
    [resolved, setKey],
  );
}

"use client";

/**
 * Makes the table instance ambient.
 *
 * Internal subcomponents still receive `table` as an explicit prop (MRT does the
 * same), but toolbar pieces a consumer composes themselves — a density toggle
 * dropped into a custom toolbar, say — can pull the instance from here instead
 * of threading it down by hand.
 */

import type { RowData } from "@tanstack/react-table";
import * as React from "react";

import type { TableCoreInstance } from "@/hooks/table/use-table-core";

// The instance is generic; the context erases it and consumers re-narrow.
// biome-ignore lint/suspicious/noExplicitAny: the context is generic-erased by design
const TableContext = React.createContext<TableCoreInstance<any> | null>(null);

interface TableProviderProps<TData extends RowData> {
  table: TableCoreInstance<TData>;
  children: React.ReactNode;
}

export function TableProvider<TData extends RowData>({
  table,
  children,
}: TableProviderProps<TData>) {
  return (
    <TableContext.Provider value={table}>{children}</TableContext.Provider>
  );
}

export function useTableContext<
  TData extends RowData,
>(): TableCoreInstance<TData> {
  const table = React.useContext(TableContext);

  if (!table) {
    throw new Error("useTableContext must be used within a <TableProvider>");
  }

  return table as TableCoreInstance<TData>;
}

/** Non-throwing variant for components that also accept an explicit `table`. */
export function useOptionalTableContext<
  TData extends RowData,
>(): TableCoreInstance<TData> | null {
  return React.useContext(TableContext) as TableCoreInstance<TData> | null;
}

