/**
 * AppSheet — port từ Payment-DIP-web, bọc `ui/sheet` thành một khung sẵn dùng:
 * header (có nút đổi vị trí trái/phải) + body cuộn được + footer.
 *
 * Khác bản gốc ở đúng hai chỗ, đều vì môi trường chứ không phải thiết kế:
 *   - Icon lấy từ `lucide-react` thay `@hugeicons` (xem `general/app-icon.tsx`).
 *   - Không persist `placement` — giống bản gốc, nó chỉ sống trong phiên mở.
 *
 * `onOpenAutoFocus` bị chặn: sheet mở ra không tự nhảy focus vào control đầu
 * tiên, tránh bàn phím ảo bật lên trên mobile và tránh nhảy trang khi body dài.
 */

import { PanelLeft, PanelRight } from "lucide-react";
import { memo, useState } from "react";

import { AppTooltip } from "@/components/data-display/app-tooltip";
import { AppButton } from "@/components/general/app-button";
import { AppIcon } from "@/components/general/app-icon";
import { Separator } from "@/components/ui/separator";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { cn } from "@/lib/utils";

// ─── Types ───────────────────────────────────────────────────────────────────

export type AppSheetPlacement = "left" | "right";

// ─── Variant mapping ─────────────────────────────────────────────────────────

/**
 * Phải ghi kèm `data-[side=right]:` vì `ui/sheet` đã đặt sẵn
 * `data-[side=right]:sm:max-w-sm` — không thắng lại selector đó thì mọi variant
 * rộng hơn `sm` đều bị kéo về 24rem.
 */
const VARIANT_CLASSES = {
  contained: "sm:max-w-md data-[side=right]:sm:max-w-md",
  narrow: "sm:max-w-sm data-[side=right]:sm:max-w-sm",
  wide: "sm:max-w-2xl data-[side=right]:sm:max-w-2xl",
  full: "w-full data-[side=right]:w-full sm:max-w-none data-[side=right]:sm:max-w-none",
} as const;

/**
 * `contained` — mặc định, cột nội dung 28rem, dùng cho form/detail thông thường.
 * `narrow` — rail gọn cho filter/quick-view (24rem).
 * `wide` — rail rộng hơn cho form nhiều section (42rem).
 * `full` — chiếm toàn bộ chiều rộng, không giới hạn max-width.
 */
export type AppSheetVariant = keyof typeof VARIANT_CLASSES;

export interface AppSheetProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;

  // Header
  title?: React.ReactNode;
  description?: React.ReactNode;

  // Body
  children?: React.ReactNode;
  bodyClassName?: string;

  // Footer — truyền `footer` để thay hẳn, không thì dùng mặc định Huỷ + Xác nhận
  footer?: React.ReactNode;
  submitLabel?: string;
  cancelLabel?: string;
  onSubmit?: () => void;
  onCancel?: () => void;
  isSubmitDisabled?: boolean;
  isSubmitting?: boolean;
  submittingText?: string;
  hideFooter?: boolean;

  // Đổi vị trí trái/phải
  defaultPlacement?: AppSheetPlacement;
  showPlacementToggle?: boolean;

  /** Kích thước sheet: `contained` (mặc định) | `narrow` | `wide` | `full`. */
  variant?: AppSheetVariant;

  className?: string;
}

function AppSheetImpl({
  open,
  onOpenChange,
  title,
  description,
  children,
  bodyClassName,
  footer,
  submitLabel = "Xác nhận",
  cancelLabel = "Hủy bỏ",
  onSubmit,
  onCancel,
  isSubmitDisabled = false,
  isSubmitting = false,
  submittingText = "Đang xử lý...",
  hideFooter = false,
  defaultPlacement = "right",
  showPlacementToggle = true,
  variant = "contained",
  className,
}: AppSheetProps) {
  const [placement, setPlacement] =
    useState<AppSheetPlacement>(defaultPlacement);

  const togglePlacement = () =>
    setPlacement((prev) => (prev === "right" ? "left" : "right"));

  const handleCancel = () => {
    onCancel?.();
    onOpenChange(false);
  };

  const defaultFooter = (
    <>
      <AppButton variant="ghost" onClick={handleCancel} disabled={isSubmitting}>
        {cancelLabel}
      </AppButton>
      <AppButton
        onClick={onSubmit}
        disabled={isSubmitDisabled}
        loading={isSubmitting}
        loadingText={submittingText}
      >
        {submitLabel}
      </AppButton>
    </>
  );

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side={placement}
        onOpenAutoFocus={(event) => event.preventDefault()}
        className={cn(
          "flex flex-col gap-0 p-0",
          VARIANT_CLASSES[variant],
          className,
        )}
      >
        <SheetHeader className="shrink-0 border-b bg-muted/40 px-3 py-2">
          <div className="flex min-w-0 items-center gap-2">
            {showPlacementToggle && (
              <div className="-ml-2 flex shrink-0 items-center gap-1">
                <AppTooltip
                  text={
                    placement === "right"
                      ? "Chuyển sang bên trái"
                      : "Chuyển sang bên phải"
                  }
                >
                  <button
                    type="button"
                    onClick={togglePlacement}
                    aria-label="Đổi vị trí"
                    className="flex h-7 w-7 items-center justify-center rounded text-muted-foreground transition-colors hover:bg-muted/80 hover:text-foreground"
                  >
                    <AppIcon
                      icon={placement === "right" ? PanelLeft : PanelRight}
                      size={16}
                    />
                  </button>
                </AppTooltip>
                <Separator orientation="vertical" className="h-8" />
              </div>
            )}

            <div className="min-w-0 flex-1">
              {title && (
                <SheetTitle className="truncate font-semibold text-sm leading-tight">
                  {title}
                </SheetTitle>
              )}
              {description && (
                <SheetDescription className="mt-0.5 text-xs leading-snug">
                  {description}
                </SheetDescription>
              )}
            </div>
          </div>
        </SheetHeader>

        <div className={cn("min-h-0 flex-1 overflow-y-auto", bodyClassName)}>
          {children}
        </div>

        {!hideFooter && (
          <SheetFooter className="shrink-0 flex-row justify-end gap-2 border-t bg-muted/40 px-3 py-2">
            {footer ?? defaultFooter}
          </SheetFooter>
        )}
      </SheetContent>
    </Sheet>
  );
}

export const AppSheet = memo(AppSheetImpl);

"use client";

/**
 * TableFilters — nút mở bộ lọc (kèm badge đếm) + sheet chứa form lọc.
 *
 * Đừng nhầm với `TableFilterToggle`: cái đó bật/tắt hàng filter ngay trên
 * header bảng, còn cái này mở một panel riêng cho các bộ lọc cấp màn hình
 * (thường là filter gửi lên API, nằm trong URL).
 *
 * Điểm mấu chốt của thiết kế — sheet KHÔNG biết gì về schema của form:
 *
 *   1. Nút "Áp dụng" nằm ở footer, tức NGOÀI thẻ <form>. Nó submit form bằng
 *      thuộc tính HTML `form={formId}`. Nhờ vậy phần khung sheet dùng lại được
 *      cho mọi màn hình mà không cần generic hoá xuống tận nút bấm.
 *   2. Form tự đăng ký hàm reset qua `registerReset`, nút "Xoá bộ lọc" chỉ gọi
 *      lại — sheet không cần biết reset nghĩa là gì với từng màn hình.
 *   3. `{open && children}` cố ý unmount form khi đóng: lần mở sau form khởi
 *      tạo lại theo `defaultValues` mới nhất, khỏi cần effect reset thủ công.
 *
 * Usage:
 *   <TableFilters
 *     formId={EMPLOYEES_FILTER_FORM_ID}
 *     activeCount={activeFilterCount}
 *     onApply={onApplyFilters}
 *   >
 *     <EmployeesFilterForm defaultValues={appliedFilters} />
 *   </TableFilters>
 */

import { ListFilter } from "lucide-react";
import * as React from "react";
import { AppSheet } from "@/components/feedback/app-sheet";
import { Button } from "@/components/ui/button";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

// ─── Labels ──────────────────────────────────────────────────────────────────

export interface TableFiltersLabels {
  trigger: string;
  title: string;
  /** Dòng phụ dưới tiêu đề — AppSheet hiện ra, không phải sr-only. */
  description: string;
  apply: string;
  clear: string;
  close: string;
}

export const defaultTableFiltersLabels: TableFiltersLabels = {
  trigger: "Bộ lọc",
  title: "Bộ lọc",
  description: "Chọn điều kiện rồi bấm Áp dụng",
  apply: "Áp dụng",
  clear: "Xoá bộ lọc",
  close: "Đóng",
};

// ─── Context ─────────────────────────────────────────────────────────────────

interface TableFiltersContextValue {
  formId: string;
  setOpen: (open: boolean) => void;
  onApply: (values: Record<string, unknown>) => void;
  /** Form gọi lúc mount để nút "Xoá bộ lọc" biết phải làm gì; `null` để gỡ. */
  registerReset: (handler: (() => void) | null) => void;
}

const TableFiltersContext =
  React.createContext<TableFiltersContextValue | null>(null);

/**
 * Truyền `TValues` để form nhận `onApply` đúng kiểu.
 *
 * Context không generic được (một instance dùng chung cho mọi màn hình), nên
 * kiểu được thu hẹp ở đây — đổi lại form không phải ép kiểu ở chỗ gọi.
 */
export function useTableFilters<
  TValues extends Record<string, unknown> = Record<string, unknown>,
>(): Omit<TableFiltersContextValue, "onApply"> & {
  onApply: (values: TValues) => void;
} {
  const context = React.useContext(TableFiltersContext);
  if (!context) {
    throw new Error("useTableFilters phải được dùng bên trong <TableFilters>");
  }
  return context;
}

// ─── Trigger ─────────────────────────────────────────────────────────────────

function TableFiltersTrigger({
  activeCount,
  label,
  disabled,
  onClick,
}: {
  activeCount: number;
  label: string;
  disabled?: boolean;
  onClick: () => void;
}) {
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <Button
          aria-label={label}
          variant="outline"
          size="icon"
          disabled={disabled}
          onClick={onClick}
          className={cn(
            "relative size-8",
            // Đang có filter thì viền đậm lên để thấy ngay từ xa, không chỉ
            // dựa vào con số nhỏ ở góc.
            activeCount > 0 && "border-primary/50",
          )}
        >
          <ListFilter className="text-muted-foreground" />
          {activeCount > 0 && (
            <span
              aria-hidden
              className="absolute -top-1 -right-1 flex h-4 min-w-4 items-center justify-center rounded-4xl bg-primary px-1 font-semibold text-[10px] text-primary-foreground leading-none"
            >
              {activeCount > 9 ? "9+" : activeCount}
            </span>
          )}
        </Button>
      </TooltipTrigger>
      <TooltipContent>{label}</TooltipContent>
    </Tooltip>
  );
}

// ─── Root ────────────────────────────────────────────────────────────────────

interface TableFiltersProps<TValues extends Record<string, unknown>> {
  /** Trùng với `id` của thẻ <form> bên trong — nút Áp dụng submit qua id này. */
  formId: string;
  /** Số filter đang bật, hiện thành badge trên nút. */
  activeCount: number;
  onApply: (values: TValues) => void;
  children: React.ReactNode;
  disabled?: boolean;
  labels?: Partial<TableFiltersLabels>;
}

export function TableFilters<TValues extends Record<string, unknown>>({
  formId,
  activeCount,
  onApply,
  children,
  disabled,
  labels: labelOverrides,
}: TableFiltersProps<TValues>) {
  const [open, setOpen] = React.useState(false);
  const resetRef = React.useRef<(() => void) | null>(null);

  const registerReset = React.useCallback((handler: (() => void) | null) => {
    resetRef.current = handler;
  }, []);

  const labels = React.useMemo(
    () => ({ ...defaultTableFiltersLabels, ...labelOverrides }),
    [labelOverrides],
  );

  const context = React.useMemo<TableFiltersContextValue>(
    () => ({
      formId,
      setOpen,
      onApply: onApply as (values: Record<string, unknown>) => void,
      registerReset,
    }),
    [formId, onApply, registerReset],
  );

  const onClear = React.useCallback(() => {
    resetRef.current?.();
    setOpen(false);
  }, []);

  return (
    <TableFiltersContext.Provider value={context}>
      <TableFiltersTrigger
        activeCount={activeCount}
        label={labels.trigger}
        disabled={disabled}
        onClick={() => setOpen(true)}
      />

      <AppSheet
        open={open}
        onOpenChange={setOpen}
        title={labels.title}
        description={labels.description}
        variant="narrow"
        bodyClassName="px-4 py-5"
        // Footer của AppSheet căn phải; ở đây cần "Xoá" dạt hẳn sang trái nên
        // tự dàn bên trong một hàng chiếm trọn chiều ngang.
        footer={
          <div className="flex w-full items-center justify-between gap-3">
            <Button variant="outline" onClick={onClear}>
              {labels.clear}
            </Button>
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => setOpen(false)}>
                {labels.close}
              </Button>
              {/* Nằm ngoài <form> nên phải submit qua `form={formId}`. */}
              <Button type="submit" form={formId}>
                {labels.apply}
              </Button>
            </div>
          </div>
        }
      >
        {open && children}
      </AppSheet>
    </TableFiltersContext.Provider>
  );
}

"use client";

/**
 * The grid's external state store.
 *
 * Grid interactions (cell focus, range selection, editing, search) fire far too
 * often for `useState` — every mousemove during a drag would re-render the whole
 * table. A `useSyncExternalStore` store lets each cell subscribe to only the
 * slice it cares about, so a drag re-renders the cells that changed and nothing
 * else.
 */

import type {
  ColumnFiltersState,
  RowSelectionState,
  SortingState,
} from "@tanstack/react-table";
import * as React from "react";

import type {
  CellPosition,
  ContextMenuState,
  PasteDialogState,
  RowHeightValue,
  SelectionState,
} from "@/types/data-grid";

export interface DataGridState {
  sorting: SortingState;
  columnFilters: ColumnFiltersState;
  rowHeight: RowHeightValue;
  rowSelection: RowSelectionState;
  selectionState: SelectionState;
  focusedCell: CellPosition | null;
  editingCell: CellPosition | null;
  cutCells: Set<string>;
  contextMenu: ContextMenuState;
  searchQuery: string;
  searchMatches: CellPosition[];
  matchIndex: number;
  searchOpen: boolean;
  lastClickedRowId: string | null;
  pasteDialog: PasteDialogState;
}

export interface DataGridStore {
  subscribe: (callback: () => void) => () => void;
  getState: () => DataGridState;
  setState: <K extends keyof DataGridState>(
    key: K,
    value: DataGridState[K],
  ) => void;
  notify: () => void;
  /** Coalesce several `setState` calls into a single notification. */
  batch: (fn: () => void) => void;
}

export function useDataGridStore<T>(
  store: DataGridStore,
  selector: (state: DataGridState) => T,
): T {
  const getSnapshot = React.useCallback(
    () => selector(store.getState()),
    [store, selector],
  );

  return React.useSyncExternalStore(store.subscribe, getSnapshot, getSnapshot);
}

"use client";

/**
 * Cột chọn dòng dùng chung cho cả data-table và data-grid.
 *
 * UX: bình thường hiện số thứ tự, hover hoặc khi dòng được chọn thì đổi thành
 * checkbox — nhờ vậy STT và ô chọn dùng chung một cột thay vì chiếm hai cột.
 * `readOnly` tắt hẳn checkbox, chỉ còn số thứ tự.
 */

import type {
  CellContext,
  ColumnDef,
  HeaderContext,
  Row,
  Table,
} from "@tanstack/react-table";
import * as React from "react";
import { Checkbox } from "@/components/ui/checkbox";
import { cn } from "@/lib/utils";

type HitboxSize = "default" | "sm" | "lg";

interface TableSelectHitboxProps {
  htmlFor: string;
  children: React.ReactNode;
  size?: HitboxSize;
  debug?: boolean;
}

function TableSelectHitbox({
  htmlFor,
  children,
  size,
  debug,
}: TableSelectHitboxProps) {
  return (
    <div
      // Chặn nổi bọt: nếu không, click vào checkbox cũng kích hoạt luôn
      // `onRowClick` gắn ở cấp <tr> (bảng master-detail) — người dùng phải
      // click 2 lần vì lần đầu bị "ăn" bởi thay đổi state của việc chọn dòng.
      onClick={(event) => event.stopPropagation()}
      className={cn(
        "group relative -my-1.5 h-[calc(100%+0.75rem)] py-1.5",
        size === "default" && "-ms-3 -me-2 ps-3 pe-2",
        size === "sm" && "-ms-3 -me-1.5 ps-3 pe-1.5",
        size === "lg" && "-mx-3 px-3",
      )}
    >
      {children}
      <label
        htmlFor={htmlFor}
        className={cn(
          "absolute inset-0 cursor-pointer",
          debug && "border border-red-500 border-dashed bg-red-500/20",
        )}
      />
    </div>
  );
}

interface TableSelectCheckboxProps
  extends Omit<React.ComponentProps<typeof Checkbox>, "id"> {
  rowNumber?: number;
  hitboxSize?: HitboxSize;
  debug?: boolean;
}

function TableSelectCheckbox({
  rowNumber,
  hitboxSize,
  debug,
  checked,
  className,
  ...props
}: TableSelectCheckboxProps) {
  const id = React.useId();

  if (rowNumber !== undefined) {
    return (
      <TableSelectHitbox htmlFor={id} size={hitboxSize} debug={debug}>
        <div
          aria-hidden="true"
          className={cn(
            "pointer-events-none absolute start-3 top-1.5 flex size-4 items-center justify-center text-muted-foreground text-xs tabular-nums transition-opacity group-hover:opacity-0",
            checked && "opacity-0",
          )}
        >
          {rowNumber}
        </div>
        <Checkbox
          id={id}
          className={cn(
            "relative transition-[shadow,border,opacity] hover:border-primary/40",
            "opacity-0 group-hover:opacity-100 data-[state=checked]:opacity-100",
            className,
          )}
          checked={checked}
          {...props}
        />
      </TableSelectHitbox>
    );
  }

  return (
    <TableSelectHitbox htmlFor={id} size={hitboxSize} debug={debug}>
      <Checkbox
        id={id}
        className={cn(
          "relative transition-[shadow,border] hover:border-primary/40",
          className,
        )}
        checked={checked}
        {...props}
      />
    </TableSelectHitbox>
  );
}

interface TableSelectHeaderProps<TData>
  extends Pick<HeaderContext<TData, unknown>, "table"> {
  readOnly?: boolean;
}

/**
 * Checkbox "chọn tất cả" ở header.
 *
 * Không dùng `TableSelectHitbox` ở đây: trick đó tính `-my-1.5
 * h-[calc(100%+0.75rem)]` dựa trên cell flex của data-grid, còn `<th>` của
 * data-table là table-cell với chiều cao cố định theo density (vd `h-8`,
 * không `py-*`) — % height tính sai khiến checkbox tràn ra ngoài ô header,
 * đè lên dòng dữ liệu đầu tiên. Header luôn chỉ là 1 checkbox tĩnh (không có
 * hiệu ứng hover-thành-số như ô dữ liệu), nên chỉ cần căn giữa bằng flex.
 */
function TableSelectHeader<TData>({
  table,
  readOnly,
}: TableSelectHeaderProps<TData>) {
  const onCheckedChange = React.useCallback(
    (value: boolean) => table.toggleAllPageRowsSelected(value),
    [table],
  );

  if (readOnly) {
    return (
      <span className="flex items-center justify-center text-muted-foreground text-xs">
        #
      </span>
    );
  }

  return (
    <span className="flex items-center justify-center">
      <Checkbox
        aria-label="Select all"
        checked={
          table.getIsAllPageRowsSelected() ||
          (table.getIsSomePageRowsSelected() && "indeterminate")
        }
        onCheckedChange={onCheckedChange}
      />
    </span>
  );
}

type GetRowNumber<TData> = (row: Row<TData>, table: Table<TData>) => number;

/**
 * Mặc định: ưu tiên chỉ số ảo của data-grid, không có thì cộng offset trang —
 * data-table chạy `manualPagination` nên `row.index` chỉ tính trong trang.
 */
function defaultGetRowNumber<TData>(row: Row<TData>, table: Table<TData>) {
  const visualIndex = table.options.meta?.getVisualRowIndex?.(row.id);
  if (visualIndex !== undefined) return visualIndex;

  const { pageIndex, pageSize } = table.getState().pagination;
  const offset = table.options.manualPagination ? pageIndex * pageSize : 0;
  return offset + row.index + 1;
}

interface TableSelectCellProps<TData>
  extends Pick<CellContext<TData, unknown>, "row" | "table"> {
  hitboxSize?: HitboxSize;
  enableRowMarkers?: boolean;
  readOnly?: boolean;
  debug?: boolean;
  getRowNumber?: GetRowNumber<TData>;
}

function TableSelectCell<TData>({
  row,
  table,
  hitboxSize,
  enableRowMarkers,
  readOnly,
  debug,
  getRowNumber = defaultGetRowNumber,
}: TableSelectCellProps<TData>) {
  const meta = table.options.meta;
  const rowNumber = enableRowMarkers ? getRowNumber(row, table) : undefined;

  const onCheckedChange = React.useCallback(
    (value: boolean) => {
      if (meta?.onRowSelect) {
        meta.onRowSelect(row.id, value, false);
      } else {
        row.toggleSelected(value);
      }
    },
    [meta, row],
  );

  const onClick = React.useCallback(
    (event: React.MouseEvent<HTMLButtonElement>) => {
      if (event.shiftKey) {
        event.preventDefault();
        meta?.onRowSelect?.(row.id, !row.getIsSelected(), true);
      }
    },
    [meta, row],
  );

  if (readOnly) {
    return (
      <div className="flex items-center ps-1 text-muted-foreground text-xs tabular-nums">
        {rowNumber ?? getRowNumber(row, table)}
      </div>
    );
  }

  return (
    <TableSelectCheckbox
      aria-label={rowNumber ? `Select row ${rowNumber}` : "Select row"}
      checked={row.getIsSelected()}
      onCheckedChange={onCheckedChange}
      onClick={onClick}
      rowNumber={rowNumber}
      hitboxSize={hitboxSize}
      debug={debug}
    />
  );
}

interface GetTableSelectColumnOptions<TData>
  extends Omit<Partial<ColumnDef<TData>>, "id" | "header" | "cell"> {
  id?: string;
  enableRowMarkers?: boolean;
  readOnly?: boolean;
  hitboxSize?: HitboxSize;
  debug?: boolean;
  getRowNumber?: GetRowNumber<TData>;
}

export function getTableSelectColumn<TData>({
  id = "select",
  size = 40,
  hitboxSize = "default",
  enableHiding = false,
  enableResizing = false,
  enableSorting = false,
  enableRowMarkers = false,
  readOnly = false,
  debug = false,
  getRowNumber,
  ...props
}: GetTableSelectColumnOptions<TData> = {}): ColumnDef<TData> {
  return {
    id,
    header: ({ table }) => (
      <TableSelectHeader table={table} readOnly={readOnly} />
    ),
    cell: ({ row, table }) => (
      <TableSelectCell
        row={row}
        table={table}
        enableRowMarkers={enableRowMarkers}
        readOnly={readOnly}
        hitboxSize={hitboxSize}
        debug={debug}
        getRowNumber={getRowNumber}
      />
    ),
    size,
    enableHiding,
    enableResizing,
    enableSorting,
    ...props,
  };
}
